/* Mock A: 70 original questions, reviewed against the supplied Bible. Held from topic practice until the form is taken. */
(function(root){'use strict';var add=root.L.addMC;
add("mock-a-001","ch13-nodes","A 61-year-old patient has a 2 cm × 2 cm anterior cervical node that is hard, nontender, and cannot be moved over the underlying tissue. Which interpretation do these characteristics most support?",
["Suggests possible malignancy","Suggests acute inflammation","Typical shotty node in a healthy adult","Suggests mild reactive enlargement"],0,
["","Tender nodes suggest inflammation, and this node is nontender.","Shotty nodes are small, mobile, discrete, and nontender, not hard and fixed.","The reactive nodes described in the source are tender, rubbery, and mobile."],
"Hard nodes that are fixed to underlying structures suggest malignancy. Inflammation produces tender nodes, and reactive or shotty nodes are mobile.");
add("mock-a-002","ch13-nodes","While palpating the lower posterior cervical triangle, the examiner feels a firm band and is unsure whether it is a lymph node or the omohyoid muscle that crosses this area. Which finding would identify it as a lymph node?",
["It rolls in only one direction under the fingers","It runs as a band across the lower triangle","It rolls both up and down and side to side","It has a larger lobulated, irregular surface"],2,
["A muscle or artery fails the two-direction rolling test, so one-direction movement does not identify a node.","A band crossing the lower triangle describes the omohyoid muscle, the structure being mistaken for a node.","","A larger lobulated, slightly irregular surface describes the submandibular gland, not a node."],
"A node can be rolled in two directions, up and down and side to side; a muscle or an artery cannot. The omohyoid crosses the lower posterior triangle and is a known node mimic.");
add("mock-a-003","ch13-thyroid","A 50-year-old patient reports cold intolerance, constipation, dry coarse skin, and modest weight gain despite a poor appetite. Which additional examination finding is most consistent with this presentation?",
["Warm, smooth, moist skin","Prolonged relaxation phase of the ankle reflex","Hyperdynamic pulsations with an accentuated S1","Increased systolic and decreased diastolic pressure"],1,
["Warm, smooth, moist skin is a sign of hyperthyroidism.","","Hyperdynamic cardiac pulsations with an accentuated S1 are listed under hyperthyroidism.","Hypothyroidism causes decreased systolic and increased diastolic pressures; this pattern is hyperthyroid."],
"The symptoms are hypothyroid, and a prolonged relaxation phase of the ankle reflex is a hypothyroid sign in Table 13-1. The other choices are all hyperthyroid signs from the opposite column.");
add("mock-a-004","ch14-acuity","A patient's right-eye visual acuity is recorded as 20/50. Which statement correctly interprets this result?",
["At 50 ft the patient reads print a normal eye reads at 20 ft","The patient correctly identified 20 of 50 letters on the chart","The patient sees better than normal because 50 exceeds 20","At 20 ft the patient reads print a normal eye reads at 50 ft"],3,
["The first number is the patient's distance from the chart, not the normal-eye distance.","Acuity notation expresses distances, not a count of letters read.","The larger the second number, the worse the vision, so 20/50 is worse than 20/20.",""],
"The first number is the testing distance and the second is the distance at which a normal eye reads that line. A larger second number means worse vision, so the reversed reading is the key trap.");
add("mock-a-005","ch14-blur","A 32-year-old with multiple sclerosis reports new blurred vision. Which cause of blurred vision does Box 14-3 link most directly to this medical history?",
["Optic neuritis","Diabetic retinopathy","Hypertensive retinopathy","Cataract"],0,
["","Box 14-3 links diabetic retinopathy to a history of diabetes, not autoimmune disease.","Box 14-3 links hypertensive retinopathy to a history of hypertension, not autoimmune disease.","Box 14-3 uses cataract as the example of gradual-onset blur, not a cause tied to autoimmune disease."],
"Box 14-3 asks about diabetes, hypertension, and autoimmune diseases because each maps to a vision problem, and optic neuritis is the one tied to autoimmune diseases like multiple sclerosis. Diabetic and hypertensive retinopathy follow the other two conditions in that row.");
add("mock-a-006","ch14-cornea","A 24-year-old patient with liver disease, tremor, and new psychiatric symptoms has a golden to red-brown ring at the periphery of each cornea. Which finding is this?",
["Corneal arcus","Kayser–Fleischer ring","Corneal scar","Pterygium"],1,
["Corneal arcus is a thin grayish-white arc, not a golden to red-brown ring.","","A corneal scar is a superficial grayish-white opacity from old injury, infection, or inflammation.","A pterygium is a triangular conjunctival thickening growing across the cornea, usually from the nasal side."],
"A golden to red-brown peripheral corneal ring from copper deposition is the Kayser–Fleischer ring of Wilson disease, which also explains the liver and neuropsychiatric findings. Corneal arcus is also peripheral but is grayish-white.");
add("mock-a-007","ch14-near","A patient has small, irregular pupils in both eyes that do not constrict to a bright light but do constrict when the patient focuses on a near object. Which pupillary abnormality is present?",
["Tonic (Adie) pupil","Horner syndrome","Argyll Robertson pupils","Oculomotor nerve paralysis"],2,
["A tonic pupil is unilaterally large with slow tonic constriction during near vision.","Horner syndrome causes a small, unilateral pupil with ipsilateral ptosis and anhidrosis.","","CN III paralysis causes a large, fixed pupil with ptosis and a down-and-out eye."],
"Small, irregular, usually bilateral pupils with a normal near reaction but no light reaction are Argyll Robertson pupils, seen in neurosyphilis. A tonic pupil also shows light-near dissociation but is unilateral and large.");
add("mock-a-008","ch14-redpain","A 66-year-old patient has sudden, severe, deep, aching eye pain with severe photophobia and decreased vision. The cornea looks steamy and the pupil is dilated and fixed. Which condition is most likely?",
["Acute iritis","Corneal injury or infection","Conjunctivitis","Acute angle-closure glaucoma"],3,
["Acute iritis causes moderate pain with a small, irregular pupil and a clear or slightly clouded cornea.","Corneal injury causes superficial pain, and the pupil is not affected unless iritis develops.","Conjunctivitis causes mild discomfort with a clear cornea, normal pupil, and unaffected vision.",""],
"A steamy cornea with a dilated, fixed pupil and severe deep pain fits acute angle-closure glaucoma, an emergency from raised intraocular pressure. Acute iritis also causes deep pain and photophobia but produces a small, irregular pupil.");
add("mock-a-009","ch15-hearing","A 62-year-old patient reports gradually worsening hearing in the right ear and fails the whispered voice test only on the right. The Weber test lateralizes to the left ear, and the right Rinne test shows air conduction longer than bone conduction. Which interpretation fits these results?",
["Right sensorineural hearing loss","Right conductive hearing loss","Left conductive hearing loss","Left sensorineural hearing loss"],0,
["","Right conductive loss would lateralize the Weber to the right ear and give a right Rinne of bone conduction equal to or longer than air.","The left ear passed the whispered voice test, so the Weber lateralizing left reflects the good ear, not a left conductive lesion.","Left sensorineural loss would lateralize the Weber to the good right ear, and the left ear hearing is normal here."],
"In unilateral sensorineural loss the Weber is heard in the good ear and the Rinne keeps the normal air-greater-than-bone pattern. Right conductive loss would instead pull the Weber toward the right and reverse the right Rinne.");
add("mock-a-010","ch15-hearing","A 30-year-old patient has gradually decreasing hearing in the left ear. The patient finds conversation easier to follow in noisy places and speaks in a soft voice. Otoscopy shows a normal ear canal and tympanic membrane. Which cause is most likely?",
["Perforated eardrum","Acoustic neuroma","Otosclerosis of the ossicles","Loud noise exposure"],2,
["A perforated eardrum causes conductive loss, but the abnormality would be visible on otoscopy.","Acoustic neuroma causes sensorineural loss, in which hearing worsens in noise and the voice may be loud.","","Noise exposure causes sensorineural loss, which worsens in noisy settings and usually begins in middle or later years."],
"Better hearing in noise, a soft voice, and onset before 40 point to conductive loss, and among conductive causes only otosclerosis usually leaves the canal and eardrum looking normal. A perforated eardrum is also conductive but would be visible.");
add("mock-a-011","ch15-nose","A patient with asthma and aspirin sensitivity reports trouble breathing through the nose. Inspection with an otoscope shows pale, saclike masses of inflamed mucosa blocking the nasal passage. Which finding is this?",
["Deviated lower septum","Septal perforation","Nasal furuncle","Nasal polyps"],3,
["A deviated lower septum is a shift of the septum itself and seldom obstructs airflow; it is not a pale saclike growth.","Septal perforation is a hole in the septum, linked to trauma, surgery, rheumatologic disease, or intranasal drugs.","A furuncle is a small, red, swollen, tender area at the nasal tip or ala, not a pale intranasal mass.",""],
"Pale saclike growths of inflamed mucosa that obstruct airflow are nasal polyps, which are associated with asthma and aspirin sensitivity. A deviated septum is common but seldom obstructs and is not a mucosal growth.");
add("mock-a-012","ch15-vertigo","A 68-year-old develops sudden vertigo. Hearing is unchanged and there is no tinnitus, but the patient has slurred speech, ataxia, and crossed motor and sensory deficits. Which cause of vertigo is most likely?",
["Vestibular neuronitis","Central vertigo","Benign positional vertigo","Acute labyrinthitis"],1,
["Vestibular neuronitis also spares hearing and lacks tinnitus but does not produce brainstem deficits such as dysarthria or crossed deficits.","","Benign positional vertigo causes brief position-triggered episodes without brainstem deficits.","Acute labyrinthitis causes unilateral sensorineural hearing loss, which this patient does not have."],
"Normal hearing and absent tinnitus fit both central vertigo and vestibular neuronitis, but accompanying brainstem deficits such as dysarthria, ataxia, and crossed motor and sensory deficits identify a central cause.");
add("mock-a-013","ch16-oral","A 19-year-old patient has fever, a red throat with thick white exudates on the tonsils, and enlarged posterior cervical lymph nodes. Which diagnosis is most suggested by this node pattern?",
["Group A streptococcal infection","Diphtheria","Candidiasis (thrush)","Infectious mononucleosis"],3,
["Group A streptococcal infection usually enlarges the anterior, not posterior, cervical nodes.","Diphtheria produces a gray pseudomembrane on a dull red throat rather than white tonsillar exudates.","Thrush produces cream-colored or bluish-white patches and is not described with fever and cervical adenopathy.",""],
"Exudative tonsillitis with fever and enlarged cervical nodes raises the probability of either group A streptococcal infection or infectious mononucleosis. Anterior cervical nodes are usually enlarged in strep, while posterior nodes point to mononucleosis.");
add("mock-a-014","ch16-oral","On the buccal mucosa near the first and second molars, the examiner sees small white specks resembling grains of salt on a red background. These spots are an early sign of which infection?",
["Candida infection","Measles (rubeola)","Secondary syphilis","Epstein-Barr virus infection"],1,
["Candida produces thick, cream-colored or bluish-white patches, not salt-grain specks.","","Secondary syphilis produces a slightly raised, oval mucous patch covered by a grayish membrane.","Epstein-Barr virus causes oral hairy leukoplakia, feathery plaques on the sides of the tongue."],
"Koplik spots, small white specks like grains of salt on a red background near the molars, are an early sign of measles, and the rash appears within a day. Candida instead forms larger adherent white plaques.");
add("mock-a-015","ch17-advent","Shortly after extubation, a patient develops a continuous, high-pitched musical sound that is loudest over the neck during inspiration. Which added sound is present?",
["Wheeze","Stridor","Rhonchi","Pleural rub"],1,
["Wheezes arise in narrowed bronchial airways and are faint or absent over the neck.","","Rhonchi are low pitched with a snoring quality, not high pitched.","A pleural rub is a discontinuous, nonmusical grating sound, often best heard in the axilla and lung bases."],
"Stridor is a continuous, high-pitched musical sound from upper airway narrowing, best heard over the neck during inspiration, and airway edema after device removal is a listed cause. Wheezes are faint or absent over the neck, which separates them from stridor.");
add("mock-a-016","ch17-advent","A patient recovering from pneumonia reports sharp chest pain with deep breaths. A low-frequency, nonmusical grating sound is heard during both inspiration and expiration, loudest in the axilla. Which added sound is described?",
["Coarse crackles","Mediastinal crunch","Rhonchi","Pleural rub"],3,
["Coarse crackles have a popping quality and change or disappear with coughing rather than a grating quality.","A mediastinal crunch is synchronous with the heartbeat, not with respiration.","Rhonchi are continuous, low-pitched sounds with a snoring quality, not a grating sound.",""],
"A pleural rub is a discontinuous, low-frequency grating sound from inflamed visceral pleura sliding on parietal pleura; it is biphasic and often best heard in the axilla and lung bases. Coarse crackles are also biphasic but pop rather than grate.");
add("mock-a-017","ch17-breath","A student auscultating a healthy adult hears breath sounds of intermediate intensity in which the inspiratory and expiratory phases are almost equal. At which site is this a normal finding?",
["Over the lower lateral lung fields","Between the scapulae","Over the trachea in the neck","Over the manubrium"],1,
["Vesicular sounds, with inspiration longer than expiration, are expected over the lower lateral lung fields.","","Tracheal sounds, heard over the trachea in the neck, also have nearly equal phases but are very loud rather than intermediate.","Bronchial sounds, loud with expiration longer than inspiration, are expected over the manubrium."],
"Bronchovesicular sounds have nearly equal inspiratory and expiratory phases with intermediate intensity and are normally heard between the scapulae and in the first and second interspaces anteriorly. Over the manubrium the normal sound is bronchial, with a longer expiratory phase.");
add("mock-a-018","ch17-breath","Over a patient's right lower lobe, the spoken sound \"ee\" is heard through the stethoscope as \"ay.\" Which transmitted voice finding is this?",
["Bronchophony","Whispered pectoriloquy","Egophony","Normal voice transmission"],2,
["Bronchophony means spoken words are heard louder, not a change in the vowel sound.","Whispered pectoriloquy means whispered words are heard louder and clearer.","","Over normal air-filled lung, a spoken \"ee\" is heard as \"ee\" and spoken words are muffled."],
"Egophony is the spoken \"ee\" heard as \"ay\" over consolidated, airless lung. Bronchophony is the related sign in which spoken words are simply louder.");
add("mock-a-019","ch17-chestdis","A patient has dullness over the right lower lobe, absent breath sounds and fremitus in that area, no adventitious sounds, and a trachea shifted toward the right. Which condition fits best?",
["Right lower lobe atelectasis","Large right pleural effusion","Right lower lobe pneumonia","Right tension pneumothorax"],0,
["","A large pleural effusion shifts the trachea toward the unaffected side, not toward the involved side.","Lobar pneumonia keeps the trachea midline and produces bronchial breath sounds with increased fremitus.","Tension pneumothorax is hyper-resonant and shifts the trachea toward the unaffected side."],
"Partial lobar obstruction (atelectasis) is dull over the airless area, may pull the trachea toward the involved side, and has absent breath sounds and fremitus while the plug persists. A large effusion is also dull with absent sounds but pushes the trachea away.");
add("mock-a-020","ch17-chestdis","A 70-year-old woman with progressive breathlessness has resonant percussion bilaterally, a midline trachea, vesicular breath sounds, normal fremitus, and late inspiratory crackles in the dependent portions of both lungs. Which condition best fits?",
["Lobar pneumonia","Chronic bronchitis","Left-sided heart failure","Asthma"],2,
["Lobar pneumonia is dull with bronchial breath sounds and increased fremitus over the involved area.","Chronic bronchitis, if it has crackles, produces scattered coarse crackles in early inspiration and expiration.","","Asthma produces wheezes with breath sounds often obscured by them and decreased fremitus."],
"In left-sided heart failure the chest stays resonant with vesicular breath sounds and normal fremitus, and the key finding is late inspiratory crackles in dependent lung portions. Lobar pneumonia also has late inspiratory crackles but only over a dull, consolidated area with bronchial sounds.");
add("mock-a-021","ch17-cough","A 58-year-old man with poor dental hygiene is seen one week after an episode of impaired consciousness. He now has fever and a cough producing purulent, foul-smelling sputum. Which condition from the cough table is most likely?",
["Chronic bronchitis","Bronchiectasis","Lung abscess","Mycoplasma pneumonia"],2,
["Chronic bronchitis is a long-standing cough with recurrent wheezing and a prolonged tobacco history, not an acute illness after a possible aspiration.","Bronchiectasis also causes foul sputum, but it is chronic with recurrent bronchopulmonary infections rather than a new illness after impaired consciousness.","","Mycoplasma pneumonia causes a dry hacking cough that may become mucoid, not purulent foul-smelling sputum."],
"Lung abscess produces purulent, foul-smelling sputum and usually follows aspiration, with oral anaerobes, poor dental hygiene, and an episode of impaired consciousness as the setting. Bronchiectasis shares the sputum description but is a chronic, recurrent process.");
add("mock-a-022","ch17-distress","While a 79-year-old patient with heart failure sleeps, the nurse observes periods of deep breathing that alternate with periods of apnea in a regular, repeating pattern. Which breathing pattern is this?",
["Cheyne-Stokes breathing","Ataxic (Biot) breathing","Kussmaul breathing","Sighing respiration"],0,
["","Ataxic breathing is irregular, with deep breaths that stop suddenly, and is linked to meningitis or medullary brain injury.","Kussmaul breathing is compensatory overbreathing from systemic acidosis and does not include periods of apnea.","Sighing respiration is breathing punctuated by frequent sighs, as in hyperventilation syndrome."],
"Cheyne-Stokes breathing alternates periods of deep breathing with apnea, is normal in older adults during sleep, and is caused by heart failure among other conditions. Ataxic breathing also has apneic periods but is irregular and points to medullary injury.");
add("mock-a-023","ch17-percussion","Over the lower right posterior chest of a patient with a large pleural effusion, the percussion note is soft, high pitched, and short, like the note over the thigh. How should this note be documented?",
["Dull","Resonant","Tympanitic","Flat"],3,
["A dull note is medium in intensity, pitch, and duration, like the note over the liver.","A resonant note is loud, low, and long, as over healthy lung.","A tympanitic note is loud, high, and longer, as over the gastric air bubble.",""],
"A flat note is soft, high pitched, and short, is produced over the thigh, and is the pathologic example for a large pleural effusion. Dull is the closest competitor but is medium in intensity and duration, like the liver.");
add("mock-a-024","ch18-cvrisk","A 58-year-old with hypertension and no known cardiovascular disease has a calculated 10-year CVD event risk of 12%. Which USPSTF statin recommendation applies?",
["Offer a moderate-intensity statin (grade B)","Selectively consider a statin (grade C)","Evidence is insufficient to decide (I statement)","Obtain a coronary calcium score before deciding"],0,
["","Selective consideration (grade C) applies to a 10-year risk of 7.5% to less than 10%.","The I statement applies to adults 76 years and older.","A coronary artery calcium score is considered only for persons who remain uncertain after the treatment discussion."],
"The USPSTF gives a grade B recommendation for moderate-intensity statins in asymptomatic adults 40 to 75 with at least one risk factor, such as hypertension, and a 10-year risk of 10% or higher. The grade C option applies only to the 7.5% to under 10% risk band.");
add("mock-a-025","ch18-cycle","An examiner hears S2 at the base. In the brief interval immediately after this sound, both semilunar valves have just closed and the mitral valve has not yet opened. Which phase of the cardiac cycle is this?",
["Rapid ventricular filling","Isovolumetric contraction","Isovolumetric relaxation","Ventricular ejection"],2,
["Rapid filling begins only after the mitral valve opens and blood pours into the LV from the LA.","Isovolumetric contraction follows S1 at the start of systole, not S2.","","Ejection occurs while the aortic valve is open, before the valve closes to produce S2."],
"Box 18-3 places isovolumetric relaxation just after S2, when the aortic and pulmonic valves have closed and all four valves are shut. Isovolumetric contraction is the corresponding all-valves-closed phase that follows S1, not S2.");
add("mock-a-026","ch18-grade","A systolic murmur is audible as soon as the stethoscope is placed on the chest. It is quiet, about equal in loudness to S1 and S2, and no thrill is palpable. How should the murmur be graded?",
["Grade 1/6","Grade 2/6","Grade 3/6","Grade 4/6"],1,
["Grade 1/6 is softer than S1 and S2 and is heard only after the listener has tuned in.","","Grade 3/6 is louder than S1 and S2, not equal to them.","Grade 4/6 requires a palpable thrill, which is absent here."],
"On the Levine scale, a murmur equal in volume to S1 and S2 that is heard immediately on placing the stethoscope is grade 2/6. A grade 1/6 murmur is softer than the heart sounds and is heard only after tuning in.");
add("mock-a-027","ch18-heave","During precordial palpation, the examiner wants to detect a heave over an enlarged ventricle. Which technique is recommended?",
["Palm or finger pads held flat on the chest","Ball of the hand pressed firmly on the chest","One fingertip placed over a single interspace","Tangential light shone across the chest wall"],0,
["","Firm pressure with the ball of the hand is the technique for detecting a thrill, not a heave.","Fingertip and single-finger palpation is used to refine the apical impulse characteristics after it is found.","Tangential lighting aids inspection of precordial movements; it is not a palpation technique."],
"To palpate heaves, use the palm and/or finger pads held flat or obliquely against the chest, because heaves are sustained lifting impulses. The ball of the hand is reserved for sensing the buzzing vibration of a thrill.");
add("mock-a-028","ch18-htn","A 48-year-old with newly diagnosed hypertension eats a high-salt diet, rarely exercises, drinks heavily, and was recently diagnosed with obstructive sleep apnea. Which of these factors is listed as a cause of secondary hypertension?",
["High salt intake","Physical inactivity","Obstructive sleep apnea","Excessive alcohol use"],2,
["High salt intake is a risk factor for primary (essential) hypertension.","Physical inactivity is a risk factor for primary (essential) hypertension.","","Excessive alcohol consumption is a risk factor for primary (essential) hypertension."],
"The chapter lists obstructive sleep apnea among the causes of secondary hypertension, which accounts for less than 5% of cases. High salt intake, physical inactivity, and excessive alcohol consumption are risk factors for primary (essential) hypertension.");
add("mock-a-029","ch18-jvp","While estimating the JVP, an examiner is unsure whether a visible pulsation on the right side of the neck is venous or arterial. Which observation favors the carotid artery?",
["The dominant movement is an inward deflection","The pulsation height falls with inspiration","Two elevations are seen with each heartbeat","Its height is unchanged when the patient sits up"],3,
["The dominant movement of the JVP is inward (x descent); the dominant carotid movement is outward.","Jugular pulsations usually fall with inspiration, while carotid height is not affected by inspiration.","A soft biphasic wave with two elevations is typical of the internal jugular pulsation.",""],
"Box 18-14 states that carotid pulsation height is unchanged by position, while jugular pulsations normally drop as the patient becomes more upright. An inward dominant movement, two elevations, and an inspiratory fall all point to the jugular vein.");
add("mock-a-030","ch18-maneuvers","A patient has bounding carotid pulses and a wide pulse pressure. Supine auscultation reveals no murmur, and the examiner suspects a soft aortic regurgitation murmur is being missed. Which position should be used next?",
["Left lateral decubitus, bell at the apex","Sitting, leaning forward, after full exhalation","Standing upright immediately after squatting","Supine, holding a deep inspiration"],1,
["Left lateral decubitus accentuates low-pitched mitral findings and left-sided S3 and S4, not the aortic regurgitation murmur.","","Standing and squatting are used to identify mitral valve prolapse and to separate hypertrophic cardiomyopathy from aortic stenosis.","Inspiration accentuates right-sided murmurs; left-sided murmurs generally increase with expiration."],
"The soft, high-pitched decrescendo diastolic murmur of aortic regurgitation is heard best with the patient sitting, leaning forward, with breath held after exhalation, using the diaphragm. The left lateral decubitus position instead brings out mitral and low-pitched findings.");
add("mock-a-031","ch18-murmurtiming","A 24-year-old has a loud, harsh, machinery-like murmur in the left second intercostal space. It is loudest in late systole, obscures S2, and fades during diastole. Which condition is most likely?",
["Venous hum","Pericardial friction rub","Patent ductus arteriosus","Ventricular septal defect"],2,
["A venous hum is a soft humming sound above the medial clavicles that is loudest in diastole and disappears supine.","A pericardial rub is a scratchy, grating sound with up to three components, not a machinery-like murmur.","","A VSD murmur is holosystolic, ending at S2, at the left third to fifth interspaces."],
"Table 18-12 describes the PDA murmur as a harsh, machinery-like continuous murmur at the left second interspace, loudest in late systole, obscuring S2, and fading in diastole. A venous hum is also continuous but is soft, above the clavicles, and loudest in diastole.");
add("mock-a-032","ch18-pmi","A 66-year-old with long-standing COPD has no palpable impulse at the usual apical location, but the most prominent impulse is felt in the epigastric area. Which interpretation is best supported?",
["Right ventricular hypertrophy","Left ventricular hypertrophy","Dextrocardia","Upward shift from a high left diaphragm"],0,
["","Left ventricular hypertrophy enlarges or laterally displaces the apical impulse; it does not move it to the epigastrium.","Dextrocardia positions the PMI on the right side of the chest, not in the epigastric area.","A high left diaphragm shifts the apical impulse upward and to the left, not down to the epigastrium."],
"Box 18-17 notes that a most prominent impulse in the xiphoid or epigastric area may indicate right ventricular hypertrophy, commonly seen in COPD. Left ventricular hypertrophy instead produces a diffuse or laterally displaced apical impulse.");
add("mock-a-033","ch18-s1s2","A 30-year-old has a split S2 in the left second intercostal space. The split is present in both inspiration and expiration, and its width does not change with breathing. Which condition does this pattern most suggest?",
["Left bundle branch block","Atrial septal defect","Calcific aortic stenosis","Pulmonary hypertension"],1,
["Left bundle branch block causes paradoxical splitting, heard on expiration and merging on inspiration.","","Calcific aortic stenosis decreases or abolishes A2, so S2 tends to be single rather than split.","Pulmonary hypertension is suggested by a loud P2, not by a split that is fixed with breathing."],
"Fixed splitting of S2 that is not affected by breathing usually reflects prolonged right ventricular systole, as in atrial septal defect. Left bundle branch block instead produces paradoxical splitting that appears on expiration.");
add("mock-a-034","ch18-systdiast","A 78-year-old with exertional syncope has a harsh crescendo-decrescendo systolic murmur loudest in the right second intercostal space that radiates into the neck. The carotid upstroke is delayed. Which lesion is most likely?",
["Hypertrophic cardiomyopathy","Mitral regurgitation","Pulmonic stenosis","Aortic stenosis"],3,
["In hypertrophic cardiomyopathy the murmur is at the left third and fourth interspaces, does not radiate to the neck, and the carotid upstroke rises quickly.","Mitral regurgitation is a blowing holosystolic murmur at the apex radiating to the left axilla.","Pulmonic stenosis is loudest at the left second and third interspaces, not the right second interspace.",""],
"Aortic stenosis produces a harsh midsystolic murmur at the right second and third interspaces that often radiates to the neck, especially on the right, with a delayed carotid upstroke. Hypertrophic cardiomyopathy is the closest competitor but does not radiate to the neck and has a brisk carotid upstroke.");
add("mock-a-035","ch19-abi","A 74-year-old patient with long-standing diabetes has an ankle-brachial index of 1.52 in the right leg. How should this value be interpreted?",
["Normal, since ankle pressure exceeds arm pressure","Probable noncompressible, calcified leg arteries","Diagnostic of peripheral arterial disease","Consistent with severe peripheral arterial disease"],1,
["The normal range ends at 1.40, so 1.52 is above normal.","","An ABI is diagnostic of PAD only when it is below 0.90.","Severe PAD is suggested by values below 0.5."],
"Values above 1.40 suggest a noncompressible calcified vessel, which is common in older adults or patients with diabetes and gives an artifactually elevated pressure. Although ankle pressure is normally higher than arm pressure, the normal ABI range stops at 1.40.");
add("mock-a-036","ch19-arteryvein","When a patient's legs are raised, both feet blanch. When the patient then sits with the legs hanging over the side of the table, the feet become dusky red. Which chronic condition does this color pattern indicate?",
["Chronic venous insufficiency","Chronic arterial insufficiency","Lymphedema","Superficial thrombophlebitis"],1,
["In venous insufficiency, color is normal or cyanotic on dependency, without pallor on elevation.","","Lymphedema causes hard, nonpitting swelling with thickened skin, not postural color change.","Superficial thrombophlebitis causes local swelling and redness, not pallor on elevation."],
"Table 19-3 describes advanced arterial insufficiency as pale, especially on elevation, and dusky red on dependency. Venous insufficiency, the closest competitor, is normal in color or cyanotic when dependent and does not blanch on elevation.");
add("mock-a-037","ch19-claud","A 66-year-old patient reports aching in both buttocks and thighs that begins after walking about two blocks and eases within a few minutes of standing still. Based on the location of the pain, which source is most suggested?",
["Aortic or iliac artery disease","Lumbar spinal stenosis","Chronic venous insufficiency","Deep vein thrombosis of the calf"],0,
["","Neurogenic pain from spinal stenosis is relieved by sitting or bending forward, not by simply standing still.","Venous insufficiency presents with leg or ankle swelling rather than exertional buttock and thigh pain relieved by rest.","DVT causes pain and swelling of the affected leg, not a reproducible exertion-and-rest pattern in the buttocks."],
"Exertional pain relieved by rest is claudication, and Box 19-6 links thigh or buttock location to more proximal disease such as aortic or iliac artery disease, whereas calf pain suggests PAD lower in the leg. Spinal stenosis also worsens with walking but is relieved by forward bending or sitting.");
add("mock-a-038","ch19-pad","Several patients are being evaluated for possible peripheral arterial disease. Which single examination finding most strongly increases the likelihood of PAD?",
["Absent pedal pulses with normal femoral and popliteal pulses","Absent femoral pulse on the side with leg symptoms","Asymmetric coolness of one foot compared with the other","An ulcer on the foot noted during skin inspection"],0,
["","An absent femoral pulse carries a likelihood ratio for PAD of 4.7, lower than the key.","Asymmetric coolness of the feet has a likelihood ratio of 5.9 for PAD, lower than the key.","A foot ulcer raises the likelihood of peripheral vascular disease to 7, lower than the key."],
"Absent pedal pulses with normal femoral and popliteal pulses raise the likelihood ratio of PAD to more than 14, the highest value given. Asymmetric coolness (LR 5.9), a foot ulcer (7), and an absent femoral pulse (4.7) all increase the likelihood less.");
add("mock-a-039","ch19-pulses","A patient's carotid, radial, and femoral pulses are all bounding and are graded +3. Which condition does the chapter associate with this pulse finding?",
["Aortic stenosis","Low cardiac output","Atherosclerotic peripheral vascular disease","Aortic regurgitation"],3,
["Aortic stenosis is associated with sluggish pulses (pulsus tardus), not bounding ones.","Low cardiac output is associated with sluggish pulses (pulsus tardus).","Atherosclerotic PVD is associated with weak pulses (pulsus parvus).",""],
"Bates states that bounding carotid, radial, and femoral pulses are present in aortic regurgitation. Aortic stenosis and low output produce sluggish pulses, and atherosclerotic PVD produces weak pulses.");
add("mock-a-040","ch19-temperature","A patient suddenly develops pain with numbness and tingling in the left foot. The left foot is cold, pale, and pulseless, while the right foot is warm with normal pulses. Which is the most likely explanation?",
["Chronic venous insufficiency","Musculoskeletal leg strain","Acute arterial occlusion","Chronic arterial insufficiency"],2,
["Venous insufficiency leaves limb temperature normal and does not cause a pulseless limb.","Musculoskeletal disorders should not affect blood supply, so they would not make the foot cold and pulseless.","","Chronic arterial insufficiency develops gradually with claudication and trophic changes, not a sudden cold, pulseless foot."],
"Sudden pain with numbness or tingling and a cold, pale, pulseless limb distal to the occlusion indicates acute arterial occlusion from embolism or thrombosis, which requires emergency treatment. The abrupt onset distinguishes it from chronic arterial insufficiency.");
add("mock-a-041","ch19-ulcers","A patient has a painful ulcer on the shin at the site of a minor injury. Pedal pulses are decreased, and the foot becomes pale when elevated. Which appearance of the skin surrounding the ulcer is most expected?",
["Thick callus around the ulcer margin","Reddish pigmentation with purpura","Atrophic skin without callus or excess pigment","Scaling, pruritic stasis dermatitis"],2,
["A surrounding callus characterizes a neuropathic ulcer at a pressure point.","Reddish pigmentation and purpura accompany venous insufficiency ulcers.","","Stasis dermatitis with redness, scaling, and pruritus accompanies venous ulcers."],
"A painful ulcer at a point of trauma with decreased pulses and pallor on elevation is an arterial insufficiency ulcer, and Table 19-4 states its surrounding skin shows no callus or excess pigment, though it may be atrophic. Callus points to a neuropathic ulcer, and pigmentation or stasis dermatitis points to a venous ulcer.");
add("mock-a-042","ch21-acute","A patient with a known hypercoagulable condition develops abrupt, severe abdominal pain. The abdomen is soft and only mildly tender, far less than the reported pain would suggest. Which condition is most likely?",
["Acute diverticulitis","Acute cholecystitis","Mesenteric ischemia","Acute pancreatitis"],2,
["Acute diverticulitis usually has gradual onset in the left lower quadrant with localized peritoneal signs and a tender mass.","Acute cholecystitis has gradual onset with signs maximal in the right upper quadrant.","","Acute pancreatitis usually shows epigastric tenderness, rebound tenderness, and localized guarding."],
"Pain out of proportion to the examination is the hallmark of mesenteric ischemia, and hypercoagulable conditions are listed aggravating factors. Pancreatitis is also severe, but the table pairs it with epigastric tenderness and guarding rather than a benign examination.");
add("mock-a-043","ch21-acute","A patient with years of heavy alcohol use develops steady, severe epigastric pain this morning that radiates straight to the back, with nausea, vomiting, and abdominal distention. Which diagnosis best fits?",
["Acute pancreatitis","Chronic pancreatitis","Biliary colic","Pancreatic cancer"],0,
["","Chronic pancreatitis has longstanding pain with a chronic or recurrent course and steatorrhea, not a new onset this morning.","Biliary colic is intermittent pain that resolves and radiates to the right scapula and shoulder.","Pancreatic cancer causes relentlessly progressive illness with painless jaundice and weight loss."],
"Acute onset of steady, severe epigastric pain radiating straight to the back with nausea, vomiting, distention, and an alcohol history matches acute pancreatitis. Chronic pancreatitis shares the location but has a longstanding course with steatorrhea and diabetes.");
add("mock-a-044","ch21-aorta","A 45-year-old patient with difficult-to-control hypertension is examined for abdominal bruits. Where should the examiner listen for a bruit that suggests renal artery stenosis?",
["Over each costovertebral angle posteriorly","Lower abdomen along the common iliac arteries","Groin area, midway between hip and pubic bones","Above and lateral to the umbilicus on both sides"],3,
["The costovertebral angle is where kidney tenderness is elicited, not a listed bruit auscultation site.","Bruits along the iliac arteries suggest aortoiliac occlusive disease or iliac aneurysm.","Femoral bruits in the groin suggest peripheral arterial disease or femoral stenosis.",""],
"Renal artery bruits are auscultated above and lateral to the umbilicus on both sides. The costovertebral angle relates to the kidneys but is used for fist percussion, not bruit detection.");
add("mock-a-045","ch21-cva","The examiner places the palm of one hand over the patient's costovertebral angle to check for kidney tenderness. How should the other hand be used?",
["Strike the resting hand with the ulnar surface of a fist","Press deeply, then release quickly to test for rebound","Strike the skin directly with the fingertips of one hand","Hook the fingers under the rib margin during inspiration"],0,
["","Pressing and quickly releasing tests rebound tenderness for peritonitis, not kidney tenderness.","Direct fingertip strikes are not the described technique; the fist strikes the hand resting on the angle.","Hooking the fingers under the costal margin is a liver palpation technique."],
"For costovertebral angle tenderness, the ulnar surface of a fist strikes the hand resting on the angle with enough force for a perceptible but painless thud. Rebound testing uses quick release of pressure and assesses the peritoneum instead.");
add("mock-a-046","ch21-hepatomeg","A patient with COPD has a liver edge palpable well below the right costal margin. Percussion shows a low upper border of liver dullness and a vertical span of 9 cm in the right midclavicular line. Which interpretation is best?",
["Hepatomegaly from cirrhosis","Downward displacement of a normal-sized liver","Riedel lobe variation in liver shape","Hepatomegaly from venous congestion"],1,
["The measured span falls within the normal range, so true enlargement from cirrhosis is not supported.","","A Riedel lobe is an elongated right lobe projecting toward the iliac crest, not a low upper border of dullness.","Venous congestion enlarges the liver, but this span is normal."],
"In COPD a flattened, low diaphragm pushes the liver down, so the edge is palpable while percussion shows a low upper edge and a normal span. A palpable edge alone does not establish hepatomegaly.");
add("mock-a-047","ch21-liver","A patient with new jaundice has had unprotected sex with multiple partners over the past year and denies injection drug use, transfusion, or recent travel. Which condition does this exposure history most directly suggest?",
["Hepatitis A","Hepatitis C","Hepatitis B","Alcoholic hepatitis"],2,
["Hepatitis A is linked to travel or contaminated food and water in areas of poor sanitation.","Hepatitis C is mainly percutaneous, and sexual transmission is described as uncommon.","","Alcoholic hepatitis requires an alcohol history, which is not described."],
"Exposure to infectious body fluids, especially through sexual contact, is the risk factor listed for hepatitis B. Hepatitis C is spread mainly by percutaneous exposure, and sexual spread is uncommon.");
add("mock-a-048","ch21-sequence","During abdominal auscultation, the examiner counts 3 clicks and gurgles over 1 full minute. How should these bowel sounds be documented?",
["Normoactive","Hypoactive","Hyperactive","Absent"],1,
["Normoactive bowel sounds occur 5 to 34 times per minute.","","Hyperactive bowel sounds occur more than 34 times per minute.","Sounds were heard during the count, so they cannot be recorded as absent."],
"Fewer than 5 sounds per minute indicates hypoactive bowel sounds. The count is below the normoactive range of 5 to 34, but sounds are present, so they are not absent.");
add("mock-a-049","ch21-special","While evaluating possible appendicitis, the examiner presses deeply in the left lower quadrant and quickly withdraws the fingers. The patient reports pain in the right lower quadrant. Which sign is positive?",
["Psoas sign","Obturator sign","Murphy sign","Rovsing sign"],3,
["The psoas sign is elicited by raising or extending the right thigh, not by left-sided pressure.","The obturator sign is elicited by flexing and internally rotating the right hip.","The Murphy sign is a halt in inspiration during right upper quadrant palpation.",""],
"Right lower quadrant pain during left-sided pressure is indirect tenderness, a positive Rovsing sign suggesting appendicitis. The psoas sign is also an appendicitis maneuver but uses thigh movement against the psoas muscle.");
add("mock-a-050","ch27-cns-pns","A 58-year-old has asymmetric weakness and wasting of the hand and forearm muscles with visible fasciculations. Sensation is intact and reflexes in the arm are decreased. Which lesion location best fits?",
["Anterior horn cell","Spinal roots and nerves","Peripheral nerve mononeuropathy","Muscle"],0,
["","A root lesion produces corresponding dermatomal sensory deficits, but sensation is intact here.","A mononeuropathy causes sensory loss in the pattern of that nerve, which is absent here.","Muscle disease causes mainly proximal weakness with no fasciculations."],
"Table 27-1 pairs segmental or focal weakness and atrophy with fasciculations, intact sensation, and decreased reflexes with the anterior horn cell (for example ALS). Spinal root and peripheral nerve lesions would add a sensory deficit.");
add("mock-a-051","ch27-cns-pns","A patient has right arm and leg weakness with spasticity and hyperreflexia. The patient also reports double vision and has slurred, poorly articulated speech. Which lesion location in Table 27-1 is most likely?",
["Cerebral cortex","Spinal cord","Brainstem","Cerebellum"],2,
["A cortical lesion causes contralateral weakness and sensory loss but not the cranial nerve deficits of diplopia and dysarthria listed for the brainstem.","A cord lesion causes weakness below the level of injury and a dermatomal sensory level, not cranial nerve deficits.","","Cerebellar lesions cause hypotonia and ataxia with normal or decreased reflexes, not spasticity and hyperreflexia."],
"Table 27-1 describes brainstem lesions as corticospinal-type weakness and spasticity plus cranial nerve deficits such as diplopia and dysarthria. A cortical lesion gives the weakness without those cranial nerve findings.");
add("mock-a-052","ch27-coma-pupils","A comatose patient with no exposure to opioids or other narcotics has pinpoint pupils smaller than 1 mm. A light reaction is visible only with a magnifying glass. Which site of damage does Table 27-16 suggest?",
["Structural damage in the midbrain","Temporal lobe herniation compressing CN III","Hemorrhage in the pons","Hypothalamic sympathetic pathway damage"],2,
["Midbrain damage gives midposition (4 to 6 mm) pupils fixed to light, not pinpoint pupils.","Herniation compressing CN III causes one fixed, dilated pupil.","","Hypothalamic sympathetic damage gives bilaterally small pupils of 1 to 2.5 mm, not under 1 mm."],
"Table 27-16 links pinpoint pupils under 1 mm to a pontine hemorrhage or to narcotics, and narcotics are excluded here. Bilaterally small pupils of 1 to 2.5 mm point instead to hypothalamic sympathetic damage or metabolic encephalopathy.");
add("mock-a-053","ch27-conscious","A hospitalized patient does not respond when the examiner speaks loudly, but opens the eyes and looks at the examiner when gently shaken. Responses are slow and somewhat confused. Which level of consciousness fits?",
["Lethargy","Obtundation","Stupor","Coma"],1,
["A lethargic patient opens the eyes and responds to a loud voice without needing touch.","","A stuporous patient arouses only after a painful stimulus, not gentle shaking.","A comatose patient remains unarousable even with repeated painful stimuli."],
"Box 27-23 tests obtundation with a gentle tactile stimulus, after which the patient opens the eyes but responds slowly and is somewhat confused. Lethargy responds to a loud voice alone.");
add("mock-a-054","ch27-cranial","When the patient says \"ah,\" the left side of the soft palate rises but the right side does not, and the uvula is pulled to the left. What does this finding indicate?",
["Right vagus nerve (CN X) weakness","Left vagus nerve (CN X) weakness","Bilateral vagus nerve (CN X) lesions","Right hypoglossal nerve (CN XII) weakness"],0,
["","The palate and uvula are pulled toward the normal side, so leftward pull points to right-sided weakness.","With a bilateral CN X lesion the palate fails to rise on both sides.","CN XII moves the tongue, not the palate and uvula."],
"In unilateral CN X paralysis, one side of the palate fails to rise and the palate and uvula are pulled toward the normal side. Leftward deviation with a nonrising right palate means the right side is weak.");
add("mock-a-055","ch27-headred","A 45-year-old with occasional headaches over many years comes in for review. Which new detail in the history most warrants prompt investigation for a secondary cause?",
["Bilateral pressure after a long workday at a desk","Throbbing pain preceded by zig-zag lines, as before","Headaches that ease with massage and relaxation","Headaches now triggered by coughing or exertion"],3,
["A pressing headache after sustained work is typical of tension headache and is not a listed warning sign.","A familiar migraine with visual aura is not a change in pattern and is not a warning sign.","Relief with massage fits tension headache and is not listed among the warning signs.",""],
"Box 27-5 lists headaches precipitated by the Valsalva maneuver or exertion as a warning sign that needs prompt investigation. The other choices describe familiar primary headache patterns that have not changed.");
add("mock-a-056","ch27-headtypes","An accountant describes steady, pressing or tightening headaches on both sides of the head that build gradually during long days of typing. The pain is mild to moderate, and there is no nausea. Which headache type is most likely?",
["Migraine without aura","Tension-type headache","Cluster headache","Headache from sinusitis"],1,
["Migraine pain is usually throbbing, moderate to severe, and often unilateral with nausea.","","Cluster pain is unilateral around the eye, severe, abrupt, and has autonomic symptoms.","Sinus headache is typically frontal or maxillary with local tenderness, nasal congestion, and discharge."],
"Table 27-4 describes tension headache as bilateral, steady, pressing or tightening, mild to moderate, provoked by sustained muscle tension such as typing, with nausea absent. Migraine is throbbing and moderate to severe with nausea.");
add("mock-a-057","ch27-nystagmus","While a patient looks upward, the examiner sees rhythmic jerking of both eyes that moves side to side. How should the plane of this nystagmus be recorded?",
["Vertical","Horizontal","Rotary","Mixed"],1,
["The plane is set by the direction the eyes move, not the upward direction of gaze.","","Rotary nystagmus involves a rotating movement, not side-to-side jerking.","Mixed describes movement in more than one plane, but these eyes move in only one plane."],
"Table 27-10 states that the plane of the movements, not the direction of gaze, defines this variable, so side-to-side jerking is horizontal even on upward gaze. Recording it as vertical confuses gaze direction with plane.");
add("mock-a-058","ch27-reflex","A patient with neck pain radiating into the right arm has diminished right biceps and brachioradialis reflexes. Which spinal segments do these reflexes test?",
["C6, C7","L2, L3, L4","C5, C6","S1"],2,
["C6 and C7 are the segments for the triceps reflex.","L2 to L4 are the segments for the knee (patellar) reflex.","","S1 is the segment for the ankle (Achilles) reflex."],
"Box 27-3 lists both the biceps and brachioradialis reflexes at cervical 5 and 6. The triceps reflex, the closest competitor, is C6 and C7.");
add("mock-a-059","ch27-tremor","A patient with hyperthyroidism holds both arms straight out in front. A fine, rapid, rhythmic tremor of the hands appears, and it stops when the hands rest in the lap. Which type of movement is this?",
["Resting tremor","Intention tremor","Asterixis","Postural tremor"],3,
["A resting tremor is most prominent at rest and lessens with movement, the opposite of this pattern.","An intention tremor appears with movement and worsens as the limb nears a target, not with holding a posture.","Asterixis is a nonrhythmic flapping from brief loss of tone, suggesting metabolic encephalopathy, not a fine rhythmic tremor.",""],
"Table 27-9 defines postural tremors as those appearing when a part actively maintains a posture, with the fine rapid tremor of hyperthyroidism as an example. Asterixis is also tested with arms extended but is a nonrhythmic flap.");
add("mock-a-060","ch28-child-face","During a newborn examination, the examiner notes a persistently high-pitched cry. Which condition is associated with this type of cry?",
["Vocal cord paralysis","Neuromuscular weakness","Hypoglycemia","Asphyxia"],2,
["Vocal cord paralysis is associated with a weak cry rather than a high-pitched one.","Neuromuscular weakness is associated with a weak cry rather than a high-pitched one.","","Asphyxia is associated with an absent cry rather than a high-pitched one."],
"A high-pitched cry is associated with increased intracranial pressure, hypoglycemia, or cri-du-chat syndrome. Vocal cord paralysis and neuromuscular weakness produce a weak cry, and asphyxia suggests an absent cry.");
add("mock-a-061","ch28-child-head","A 5-month-old has had vomiting and diarrhea for 2 days. With the infant lying down and calm, the anterior fontanelle feels depressed. What does this finding most suggest?",
["Increased intracranial pressure","Dehydration","Congenital hypothyroidism","Craniosynostosis"],1,
["Increased intracranial pressure produces a bulging, tense fontanelle, not a depressed one.","","Congenital hypothyroidism is linked to enlarged fontanelles or delayed closure, not a sunken fontanelle.","Craniosynostosis is premature suture closure with bony ridges and abnormal head shape, not a depressed fontanelle."],
"A depressed fontanelle, assessed with the infant lying down, suggests dehydration, which fits the vomiting and diarrhea. Increased intracranial pressure causes the opposite finding, a bulging and tense fontanelle.");
add("mock-a-062","ch28-child-murmur","A well 8-year-old has an early-to-midsystolic, slightly harsh murmur heard just above the clavicles and over the neck, louder on the left. The precordium is otherwise quiet, and the murmur disappears with carotid compression. Which explanation is most likely?",
["Aortic valve stenosis","Ventricular septal defect","Patent ductus arteriosus","Benign carotid-area murmur"],3,
["Aortic stenosis is an ejection murmur centered at the midsternum or upper right sternal border that radiates to the carotids, so the precordium would not be quiet.","A ventricular septal defect produces a harsh pansystolic murmur at the lower left sternal border.","A patent ductus arteriosus produces a continuous machinery-like murmur at the upper left sternal border.",""],
"An early and midsystolic, slightly harsh murmur heard in the carotid area or above the clavicles that is eliminated by carotid compression is one of the benign childhood murmurs in Box 28-50. Aortic stenosis can be heard over the carotids but originates at the upper right sternal border and is not abolished by carotid compression.");
add("mock-a-063","ch28-child-resp","A 6-month-old is observed for a full 60 seconds during quiet sleep and has a steady respiratory rate of 64 breaths/min. How should this rate be interpreted?",
["Tachypnea for age","Normal sleeping rate for age","Periodic breathing","Bradypnea for age"],0,
["","Normal infant rates are 30 to 40 breaths/min asleep, so 64 is well above the sleeping range.","Periodic breathing alternates rapid and slow rates, but this rate is steady.","Bradypnea is a slow rate; 64 breaths/min is fast for an infant."],
"For infants 2 to 12 months, tachypnea is a rate above 50/min, and a sleeping infant should breathe about 30 to 40 times per minute; 64 also exceeds the 25 to 60 infant range. A steady rate of 64 does not fit periodic breathing, which alternates fast and slow periods.");
add("mock-a-064","ch29-preg-head","During the head and neck examination of a patient at 20 weeks' gestation, which finding requires further investigation rather than being attributed to normal pregnancy?",
["Modest symmetric enlargement of the thyroid","Brownish patches over the forehead and cheeks","A discrete nodule within the thyroid gland","Nasal congestion with occasional epistaxis"],2,
["Modest symmetric enlargement from glandular hyperplasia and increased vascularity is normal in pregnancy.","Irregular brownish facial patches are chloasma (melasma), the expected mask of pregnancy.","","Nasal congestion and epistaxis are expected consequences of the hematologic changes of normal pregnancy."],
"Thyroid nodules, goiters, and enlargement beyond modest symmetric growth are abnormal in pregnancy and require investigation. Modest symmetric enlargement is the closest competitor, but it reflects normal glandular hyperplasia and increased vascularity.");
add("mock-a-065","ch29-preg-heart","A patient at 32 weeks' gestation undergoes cardiac auscultation. Which finding should prompt further investigation rather than reassurance?",
["A soft systolic murmur","A diastolic murmur","A continuous mammary souffle","An exaggerated split S1"],1,
["Systolic murmurs occur in up to 90% of pregnant patients and usually reflect the increased circulating volume.","","A mammary souffle is commonly heard in late pregnancy or lactation from increased breast blood flow.","An exaggerated split S1 is listed among the normal cardiovascular changes of pregnancy."],
"A diastolic murmur in pregnancy is never normal and warrants further evaluation. A soft systolic murmur is the tempting alternative, but systolic murmurs are common and usually physiologic.");
add("mock-a-066","ch30-geriatric","An 86-year-old has diminished strength and endurance and has declined sharply after each minor illness. Which validated tool targets this geriatric syndrome?",
["Edmonton Frail Scale","Braden Scale","Mini Nutritional Assessment","Delirium Observation Screening Scale"],0,
["","The Braden Scale predicts pressure ulcer risk.","The Mini Nutritional Assessment screens for malnutrition, not vulnerability to stressors.","The DOSS screens for delirium, which involves acute confusion not described here."],
"Increased vulnerability to stressors with diminished strength, endurance, and physiologic function defines frailty, assessed with the Fried Frailty Criteria, Frailty Index, or Edmonton Frail Scale. The Mini Nutritional Assessment is tempting because weakness can accompany poor nutrition, but it targets malnutrition.");
add("mock-a-067","ch30-older-body","A healthy 78-year-old has a resting blood pressure of 162/68 mm Hg. Which age-related change best accounts for this pattern of readings?",
["Arterial stiffening that raises systolic pressure","Decline in maximal heart rate with exertion","Degeneration of the cardiac conduction system","Reduced efficiency of lymphatic drainage"],0,
["","A lower maximal heart rate affects exercise tolerance, not the resting pressure pattern.","Conduction system degeneration increases arrhythmia risk rather than widening pulse pressure.","Less efficient lymphatic drainage may lead to edema, not a widened pulse pressure."],
"Arterial stiffness raises systolic pressure while diastolic pressure plateaus or falls, producing the widened pulse pressure seen here. The other options are real aging changes, but they affect exercise tolerance, rhythm, or edema rather than blood pressure.");
add("mock-a-068","ch30-older-heent","An 80-year-old has age-related hearing loss (presbycusis) that is still in its early stage. Which sounds are typically affected first?",
["Low-frequency sounds","Middle-frequency sounds","All frequencies equally","High-frequency sounds"],3,
["Presbycusis affects high-frequency sounds initially, not low-frequency sounds.","Presbycusis affects high-frequency sounds initially, not the middle frequencies.","Presbycusis begins selectively with high-frequency sounds rather than affecting all frequencies at once.",""],
"Age-related hearing loss (presbycusis) affects high-frequency sounds initially. Because it can impair the patient's ability to follow verbal instructions, hearing should be assessed with techniques sensitive to this loss.");
add("mock-a-069","ch11-delirium","A 79-year-old has 3 years of slowly worsening forgetfulness and now needs help managing finances. The patient is alert, attends well during the interview, and is oriented, but has trouble recalling recent events and learning new information. Which condition best fits?",
["Dementia","Delirium","Age-related cognitive decline","Mild cognitive impairment"],0,
["","Delirium has an acute onset with fluctuating attention and a disturbed level of consciousness.","Age-related cognitive decline does not significantly interfere with daily activities.","Mild cognitive impairment does not significantly interfere with daily activities, yet this patient needs help with finances."],
"Insidious onset, preserved alertness and attention, and impaired recent memory and new learning with functional decline fit dementia. Mild cognitive impairment also affects memory but, by definition, without significant interference in daily activities.");
add("mock-a-070","ch11-delirium","A hospital unit is designing a multicomponent program to reduce delirium in older inpatients. Which measure is consistent with the risk factors such programs target?",
["Giving a sedative-hypnotic at bedtime for sleep","Storing glasses and hearing aids away during the stay","Protecting sleep and encouraging early mobility","Limiting oral fluids to reduce nighttime toileting"],2,
["Prescription of psychoactive drugs is itself a risk factor these programs aim to reduce.","Visual and hearing impairment are targeted risk factors, so removing sensory aids would add risk.","","Dehydration is a targeted risk factor, so restricting fluids would add risk."],
"Multicomponent interventions that target sleep deprivation, immobility, sensory impairment, dehydration, and psychoactive drugs can reduce delirium incidence, so protecting sleep and promoting mobility fits the approach. A bedtime sedative-hypnotic adds a psychoactive drug, which is a listed risk factor.");
root.L.ITEMS.forEach(function(it){if(it.id.indexOf('mock-a-')===0)it.pool='x';});
})(typeof window!=='undefined'?window:globalThis);
